// Builds src/core/icon-sets.data.ts from three free icon sets.
// The packages are NOT project dependencies (the generated file is committed).
// To regenerate:
//   npm i --no-save lucide-static @phosphor-icons/core @tabler/icons
//   node scripts/build-icon-sets.mjs
// Licences: Lucide (ISC), Phosphor (MIT), Tabler (MIT) - see THIRD_PARTY_NOTICES.md.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import process from 'node:process';

const modules = process.env.ICON_MODULES ?? 'node_modules';

// meaning -> [lucide, phosphor (regular), tabler (outline)]
const MAP = {
  search: ['search', 'magnifying-glass', 'search'],
  menu: ['menu', 'list', 'menu-2'],
  close: ['x', 'x', 'x'],
  home: ['house', 'house', 'home'],
  user: ['user', 'user', 'user'],
  settings: ['settings', 'gear', 'settings'],
  cart: ['shopping-cart', 'shopping-cart', 'shopping-cart'],
  heart: ['heart', 'heart', 'heart'],
  star: ['star', 'star', 'star'],
  share: ['share-2', 'share-network', 'share'],
  bell: ['bell', 'bell', 'bell'],
  play: ['play', 'play', 'player-play'],
  pause: ['pause', 'pause', 'player-pause'],
  download: ['download', 'download-simple', 'download'],
  upload: ['upload', 'upload-simple', 'upload'],
  mail: ['mail', 'envelope-simple', 'mail'],
  plus: ['plus', 'plus', 'plus'],
  minus: ['minus', 'minus', 'minus'],
  trash: ['trash-2', 'trash', 'trash'],
  edit: ['pencil', 'pencil-simple', 'pencil'],
  check: ['check', 'check', 'check'],
  bookmark: ['bookmark', 'bookmark-simple', 'bookmark'],
  info: ['info', 'info', 'info-circle'],
  help: ['circle-question-mark', 'question', 'help-circle'],
  globe: ['globe', 'globe', 'world'],
  calendar: ['calendar', 'calendar-blank', 'calendar'],
  filter: ['funnel', 'funnel', 'filter'],
  more: ['ellipsis', 'dots-three', 'dots'],
  lock: ['lock', 'lock', 'lock'],
  logout: ['log-out', 'sign-out', 'logout'],
  camera: ['camera', 'camera', 'camera'],
  image: ['image', 'image', 'photo'],
  link: ['link', 'link', 'link'],
  phone: ['phone', 'phone', 'phone'],
  chat: ['message-circle', 'chat-circle', 'message-circle'],
  'arrow-left': ['arrow-left', 'arrow-left', 'arrow-left'],
  'arrow-right': ['arrow-right', 'arrow-right', 'arrow-right'],
  'chevron-down': ['chevron-down', 'caret-down', 'chevron-down'],
  'chevron-up': ['chevron-up', 'caret-up', 'chevron-up'],
  'chevron-left': ['chevron-left', 'caret-left', 'chevron-left'],
  'chevron-right': ['chevron-right', 'caret-right', 'chevron-right'],
  external: ['external-link', 'arrow-square-out', 'external-link'],
  refresh: ['refresh-cw', 'arrows-clockwise', 'refresh'],
  'thumbs-up': ['thumbs-up', 'thumbs-up', 'thumb-up'],
  location: ['map-pin', 'map-pin', 'map-pin'],
  eye: ['eye', 'eye', 'eye'],
  volume: ['volume-2', 'speaker-high', 'volume'],
  mic: ['mic', 'microphone', 'microphone'],
};

const files = {
  lucide: (name) => join(modules, 'lucide-static/icons', `${name}.svg`),
  phosphor: (name) => join(modules, '@phosphor-icons/core/assets/regular', `${name}.svg`),
  tabler: (name) => join(modules, '@tabler/icons/icons/outline', `${name}.svg`),
};

/** Minimal mask SVG: only shapes, painted black (a mask only uses alpha). */
function clean(svg, set) {
  const viewBox = /viewBox="([^"]+)"/.exec(svg)?.[1] ?? '0 0 24 24';
  const inner = svg
    .replace(/<!--[\s\S]*?-->/g, '')
    .replace(/^[\s\S]*?<svg[^>]*>/, '')
    .replace(/<\/svg>\s*$/, '')
    .replace(/<path stroke="none" d="M0 0h24v24H0z" fill="none"\s*\/>/g, '') // tabler's bounding box
    .replace(/\s*\n\s*/g, '')
    .replace(/currentColor/g, '#000')
    .trim();
  const paint =
    set === 'phosphor'
      ? 'fill="#000"'
      : 'fill="none" stroke="#000" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"';
  if (/<(script|foreignObject|image|use)\b/i.test(inner) || /\son\w+=/i.test(inner)) {
    throw new Error(`Unexpected content in ${set} icon`);
  }
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${viewBox}" ${paint}>${inner}</svg>`;
}

const out = { lucide: {}, phosphor: {}, tabler: {} };
for (const [meaning, names] of Object.entries(MAP)) {
  ['lucide', 'phosphor', 'tabler'].forEach((set, i) => {
    out[set][meaning] = clean(readFileSync(files[set](names[i]), 'utf8'), set);
  });
}

const header = `// GENERATED by scripts/build-icon-sets.mjs - do not edit by hand.
// Icons: Lucide (ISC), Phosphor (MIT), Tabler (MIT). See THIRD_PARTY_NOTICES.md.
`;
writeFileSync(
  'src/core/icon-sets.data.ts',
  `${header}
export const ICON_MEANINGS = ${JSON.stringify(Object.keys(MAP))} as const;
export type IconMeaning = (typeof ICON_MEANINGS)[number];

/** Mask-ready SVG markup (black on transparent) per set and meaning. */
export const ICON_SVGS: Readonly<Record<'lucide' | 'phosphor' | 'tabler', Readonly<Record<IconMeaning, string>>>> = ${JSON.stringify(out, null, 2)};
`,
);
process.stdout.write(`Wrote ${Object.keys(MAP).length} icons x 3 sets` + '\n');
